    pub fn from_id(
        cache: &ValidationCache,
        id: &OutlineId,
    ) -> Result<Self, OutlineError>;
    pub fn from_source(
        cache: &ValidationCache,
        filename: impl AsRef<Path>,
        source: Arc<str>,
    ) -> Result<Self, OutlineError>;
    pub fn from_path_with<L: OutlineLang>(
        cache: &ValidationCache,
        language: &L,
